//! F/D arithmetic-core verification against the pinned Berkeley SoftFloat 3e
//! reference vectors (contract U2).
//!
//! `tools/fpu/fpu-reference-v1.tsv` is generated by
//! `tools/fpu/gen_fpu_vectors.c` from Berkeley SoftFloat Release 3e, pinned
//! and reproduced by `tools/fpu/gen_fpu_vectors.sh`. Each row is
//! `op rm a b c result flags`, with `fflags` bit order. See
//! `tools/fpu/README.md` for the generator, its pin, the seed/level and the
//! two documented RISC-V adjustments the generator applies (canonical NaN
//! results and the integer-conversion saturation table).
//!
//! The fused multiply-add rows are for `FMADD`. The other three fused forms
//! are exactly `FMADD` with negated operands, so each reference row also
//! checks `FMSUB`/`FNMSUB`/`FNMADD` with the corresponding sign bits flipped.

use ruscv_sim::fpu::arith::{double, single, FpFlags, Rounding};

const VECTOR_FILE: &str = "tools/fpu/fpu-reference-v1.tsv";
const SIGN32: u32 = 0x8000_0000;
const SIGN64: u64 = 0x8000_0000_0000_0000;

fn rounding(name: &str) -> Rounding {
    match name {
        "RNE" => Rounding::Rne,
        "RTZ" => Rounding::Rtz,
        "RDN" => Rounding::Rdn,
        "RUP" => Rounding::Rup,
        "RMM" => Rounding::Rmm,
        // The comparison rows carry no rounding mode; the comparisons ignore it.
        "-" => Rounding::Rne,
        other => panic!("unknown rounding mode {other}"),
    }
}

fn flags(bits: &str) -> FpFlags {
    FpFlags::from_bits(u8::from_str_radix(bits, 16).expect("flag field"))
        .expect("flags within the five defined bits")
}

fn hex(value: &str) -> u64 {
    u64::from_str_radix(value, 16).unwrap_or_else(|e| panic!("hex operand {value:?}: {e}"))
}

struct Row<'a> {
    op: &'a str,
    rm: &'a str,
    a: u64,
    b: u64,
    c: Option<u64>,
    result: u64,
    flags: FpFlags,
}

impl<'a> Row<'a> {
    fn parse(line: &'a str) -> Self {
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 7, "malformed vector row: {line}");
        Row {
            op: fields[0],
            rm: fields[1],
            a: hex(fields[2]),
            b: if fields[3] == "-" { 0 } else { hex(fields[3]) },
            c: if fields[4] == "-" {
                None
            } else {
                Some(hex(fields[4]))
            },
            result: hex(fields[5]),
            flags: flags(fields[6]),
        }
    }
}

fn vectors() -> String {
    // `FPU_VECTOR_FILE` lets a maintainer replay a locally regenerated,
    // larger vector set through the same assertions; the committed file is
    // the default.
    let path = std::env::var("FPU_VECTOR_FILE")
        .unwrap_or_else(|_| format!("{}/{}", env!("CARGO_MANIFEST_DIR"), VECTOR_FILE));
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {path}: {e}"))
}

/// Dispatch one reference row through the core, returning the routed
/// operation name so a failure names the instruction under test.
fn execute(row: &Row<'_>) -> Vec<(&'static str, u64, FpFlags)> {
    macro_rules! one {
        ($name:literal, $call:expr) => {{
            let (result, flags) = $call;
            vec![($name, result as u64, flags)]
        }};
    }
    let rm = rounding(row.rm);
    let (a, b) = (row.a, row.b);
    let (a32, b32) = (a as u32, b as u32);
    match row.op {
        "f32_add" => one!("f32_add", single::add(a32, b32, rm)),
        "f32_sub" => one!("f32_sub", single::sub(a32, b32, rm)),
        "f32_mul" => one!("f32_mul", single::mul(a32, b32, rm)),
        "f32_div" => one!("f32_div", single::div(a32, b32, rm)),
        "f32_sqrt" => one!("f32_sqrt", single::sqrt(a32, rm)),
        "f32_fmadd" => {
            let c = row.c.expect("FMA addend") as u32;
            [
                ("f32_fmadd", single::fmadd(a32, b32, c, rm)),
                ("f32_fmsub", single::fmsub(a32, b32, c ^ SIGN32, rm)),
                ("f32_fnmsub", single::fnmsub(a32 ^ SIGN32, b32, c, rm)),
                (
                    "f32_fnmadd",
                    single::fnmadd(a32 ^ SIGN32, b32, c ^ SIGN32, rm),
                ),
            ]
            .into_iter()
            .map(|(name, (result, flags))| (name, result as u64, flags))
            .collect()
        }
        "f64_add" => one!("f64_add", double::add(a, b, rm)),
        "f64_sub" => one!("f64_sub", double::sub(a, b, rm)),
        "f64_mul" => one!("f64_mul", double::mul(a, b, rm)),
        "f64_div" => one!("f64_div", double::div(a, b, rm)),
        "f64_sqrt" => one!("f64_sqrt", double::sqrt(a, rm)),
        "f64_fmadd" => {
            let c = row.c.expect("FMA addend");
            vec![
                ("f64_fmadd", double::fmadd(a, b, c, rm)),
                ("f64_fmsub", double::fmsub(a, b, c ^ SIGN64, rm)),
                ("f64_fnmsub", double::fnmsub(a ^ SIGN64, b, c, rm)),
                ("f64_fnmadd", double::fnmadd(a ^ SIGN64, b, c ^ SIGN64, rm)),
            ]
            .into_iter()
            .map(|(name, (result, flags))| (name, result, flags))
            .collect()
        }
        "f32_to_i32" => one!("f32_to_i32", single::to_i32(a32, rm)),
        "f32_to_ui32" => one!("f32_to_ui32", single::to_ui32(a32, rm)),
        "f32_to_i64" => one!("f32_to_i64", single::to_i64(a32, rm)),
        "f32_to_ui64" => one!("f32_to_ui64", single::to_ui64(a32, rm)),
        "f64_to_i32" => one!("f64_to_i32", double::to_i32(a, rm)),
        "f64_to_ui32" => one!("f64_to_ui32", double::to_ui32(a, rm)),
        "f64_to_i64" => one!("f64_to_i64", double::to_i64(a, rm)),
        "f64_to_ui64" => one!("f64_to_ui64", double::to_ui64(a, rm)),
        "i32_to_f32" => one!("i32_to_f32", single::from_i32(a as i32, rm)),
        "ui32_to_f32" => one!("ui32_to_f32", single::from_ui32(a as u32, rm)),
        "i64_to_f32" => one!("i64_to_f32", single::from_i64(a as i64, rm)),
        "ui64_to_f32" => one!("ui64_to_f32", single::from_ui64(a, rm)),
        "i32_to_f64" => one!("i32_to_f64", double::from_i32(a as i32, rm)),
        "ui32_to_f64" => one!("ui32_to_f64", double::from_ui32(a as u32, rm)),
        "i64_to_f64" => one!("i64_to_f64", double::from_i64(a as i64, rm)),
        "ui64_to_f64" => one!("ui64_to_f64", double::from_ui64(a, rm)),
        "f32_to_f64" => one!("f32_to_f64", double::from_single(a32)),
        "f64_to_f32" => one!("f64_to_f32", single::from_double(a, rm)),
        "f32_eq" => one!("f32_eq", bool_result(single::eq(a32, b32))),
        "f32_lt" => one!("f32_lt", bool_result(single::lt(a32, b32))),
        "f32_le" => one!("f32_le", bool_result(single::le(a32, b32))),
        "f64_eq" => one!("f64_eq", bool_result(double::eq(a, b))),
        "f64_lt" => one!("f64_lt", bool_result(double::lt(a, b))),
        "f64_le" => one!("f64_le", bool_result(double::le(a, b))),
        other => panic!("unknown reference operation {other}"),
    }
}

fn bool_result((value, flags): (bool, FpFlags)) -> (u64, FpFlags) {
    (value as u64, flags)
}

#[test]
fn reference_vectors_match_the_core() {
    let text = vectors();
    let expected_rows = text.lines().filter(|line| !line.trim().is_empty()).count();
    let mut rows = 0usize;
    let mut failures = Vec::new();
    for (line_number, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        rows += 1;
        let row = Row::parse(line);
        for (name, got_result, got_flags) in execute(&row) {
            if got_result != row.result || got_flags != row.flags {
                failures.push(format!(
                    "line {}: {name} rm={} a={:#x} b={:#x} c={:?}: got {got_result:#x} {got_flags:?}, \
                     want {:#x} {:?}",
                    line_number + 1,
                    row.rm,
                    row.a,
                    row.b,
                    row.c,
                    row.result,
                    row.flags
                ));
                if failures.len() >= 20 {
                    break;
                }
            }
        }
        if failures.len() >= 20 {
            break;
        }
    }
    assert_eq!(rows, expected_rows, "vector file contains unprocessed rows");
    assert!(
        rows > 10_000,
        "reference vector file looks truncated: {rows} rows"
    );
    assert!(
        failures.is_empty(),
        "{} reference mismatches (first {}):\n{}",
        failures.len(),
        failures.len(),
        failures.join("\n")
    );
}
